cy.document().then((doc) => {
  const all = doc.querySelectorAll("input");
  const search = doc.querySelector('input[placeholder="Search"]');
  const lines = [];
  lines.push("DOC all inputs: " + all.length + " | Search found: " + !!search);
  all.forEach((el, i2) => {
    lines.push("DOC input[" + i2 + "] ph='" + (el.getAttribute("placeholder") || "") + "' cls='" + (el.getAttribute("class") || "").slice(0, 40) + "'");
  });
  if (search) {
    lines.push("SEARCH parent chain: " + (() => {
      let e = search;
      const p = [];
      while (e && p.length < 6) {
        p.push(e.tagName + "." + ((e.getAttribute("class") || "").split(" ")[0] || ""));
        e = e.parentElement;
      }
      return p.join(" > ");
    })());
  }
  cy.writeFile("cypress/_probe_inputs.txt", lines.join("\n"));
});
